# This problem is a variant of the classic knapsack problem and can be solved using dynamic programming.
def f(N, W, P, tups):
    # Create a 2D array to store the maximum possible price for each node and capacity
    dp = [[-1]*(W+1) for _ in range(N+1)]

    # Initialize base case: if there are no nodes or no budget, the price is zero
    for i in range(W+1):
        dp[0][i] = 0

    # Fill up the dp table
    for i in range(1, N+1):
        for j in range(W+1):
            # Consider only including the current node if the budget permits
            if j >= P[i-1]:
                dp[i][j] = max(dp[i-1][j], P[i-1] + dp[i-1][j-P[i-1]])
            else:
                dp[i][j] = dp[i-1][j]

    # Find the maximum price for each node and capacity
    max_price = dp[N][W]

    # Use a priority queue to find the maximum edge to remove to maximize the price
    import heapq
    pq = []

    for u, v, c in tups:
        if dp[v-1][W-c] == max_price:
            heapq.heappush(pq, (-c, u, v))

    if pq:
        return -pq[0][0]
    else:
        return -1

